const $=id=>document.getElementById(id);let rows=[];const raw='https://raw.githubusercontent.com/manishklach/InferenceFlow/main/docs/gpu-rates/observations.jsonl';
const money=n=>'$'+Number(n).toFixed(3), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){try{let response=await fetch(raw+'?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('Repository unavailable');rows=(await response.text()).trim().split('\n').filter(Boolean).map(JSON.parse).filter(r=>!r.invalidated);$('raw').href=raw;for(const a of document.querySelectorAll('a[download]')){const f=a.getAttribute('href');if(f==='hourly.csv'||f==='daily.csv')a.href=raw.replace('observations.jsonl',f)}status(false)}catch(e){try{const r=await fetch('observations.jsonl');if(!r.ok)throw e;rows=(await r.text()).trim().split('\n').filter(Boolean).map(JSON.parse).filter(r=>!r.invalidated);status(true)}catch{$('notice').textContent='Price history is unavailable. Please try again later.';return}}const selected=$('model').value;$('model').innerHTML=[...new Set(rows.filter(r=>r.gpu_id!=='unknown').map(r=>r.gpu))].sort().map(m=>`<option>${esc(m)}</option>`).join('');$('model').value=selected||'L4';render()}
function status(fallback){const last=rows.reduce((a,r)=>r.observed_at_utc>a?r.observed_at_utc:a,'');const stale=Date.now()-Date.parse(last)>90*60000;$('notice').textContent=`${fallback?'Published snapshot \u00b7 ':''}${stale?'STALE \u2014 ':''}Latest observation: ${new Date(last).toLocaleString()} \u00b7 timestamps stored in UTC. ${stale?'Collector has not supplied a recent snapshot.':'Hourly collection requested; no quote is guaranteed until deployment.'}`}
function render(){const exact=rows.find(r=>r.gpu.toLowerCase()===$('search').value.trim().toLowerCase());if(exact)$('model').value=exact.gpu;const latest=new Map;for(const r of rows)latest.set(r.gpu+'|'+r.cloud,r);const filtered=[...latest.values()].filter(r=>r.gpu_id!=='unknown').filter(r=>(!$('search').value||r.gpu.toLowerCase().includes($('search').value.toLowerCase()))&&(!$('cloud').value||r.cloud===$('cloud').value)&&(!$('stock').value||(r.availability!=='NONE'&&r.cloud_supported!==false))).sort((a,b)=>a.gpu_usd_per_hour-b.gpu_usd_per_hour);$('count').textContent=`${new Set(rows.filter(r=>r.gpu_id!=='unknown').map(r=>r.gpu)).size} named GPU models recorded (provider placeholder retained in raw data) \u00b7 ${filtered.length} cloud quotes shown`;$('latest').innerHTML=filtered.map(r=>`<tr><td>${esc(r.gpu)}</td><td>${r.vram_gb} GB</td><td>${esc(r.cloud)}</td><td>${r.cloud_supported===false||r.gpu_usd_per_hour<=0?'—':money(r.gpu_usd_per_hour)}</td><td>${r.cloud_supported===false||r.gpu_usd_per_hour<=0?'—':money(r.gpu_usd_per_hour*24)}</td><td class="stock ${r.availability==='NONE'?'none':''}">${r.cloud_supported===false?'UNSUPPORTED':esc(r.availability)}</td><td>${esc(r.observed_at_utc.slice(0,19))}</td></tr>`).join('');draw()}
function draw(){const selected=rows.filter(r=>r.gpu===$('model').value&&r.cloud_supported!==false&&r.gpu_usd_per_hour>0),dates=selected.map(r=>Date.parse(r.observed_at_utc));if(!dates.length)return;const start=Math.min(...dates),end=Math.max(...dates),max=Math.max(...selected.map(r=>r.gpu_usd_per_hour))*1.15;let svg='<rect width="100%" height="100%" fill="#fff"/>';for(let i=0;i<5;i++){const y=250-i*50;svg+=`<path d="M70 ${y}H900" stroke="#e0e6d8"/><text x="5" y="${y+5}" font-size="13">${money(max*i/4)}</text>`}for(const [index,cloud]of ['COMMUNITY','SECURE'].entries()){const data=selected.filter(r=>r.cloud===cloud),color=index?'#2f5841':'#b57128',points=data.map(r=>[70+820*(Date.parse(r.observed_at_utc)-start)/Math.max(1,end-start),250-200*r.gpu_usd_per_hour/max]);svg+=`<polyline fill="none" stroke="${color}" stroke-width="2" points="${points.map(p=>p.join(',')).join(' ')}"/>`;points.forEach((p,i)=>svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="5" stroke="${color}" stroke-width="2" fill="${data[i].availability==='NONE'?'white':color}"/>`);svg+=`<text x="${100+index*230}" y="290" fill="${color}">${cloud}</text>`}$('chart').setAttribute('viewBox','0 0 940 310');$('chart').innerHTML=svg;$('chart-note').textContent=`${new Date(start).toISOString()} \u2192 ${new Date(end).toISOString()}. Hollow points indicate no stock. ${new Set(dates).size===1?'Only one snapshot exists for this model; no trend established.':''}`;const groups=new Map;for(const r of selected){const key=r.observed_at_utc.slice(0,10)+'|'+r.cloud;groups.set(key,[...(groups.get(key)||[]),r.gpu_usd_per_hour])}$('daily').innerHTML=[...groups].sort().map(([key,p])=>`<tr><td>${key.split('|')[0]}</td><td>${key.split('|')[1]}</td><td>${p.length}</td><td>${money(Math.min(...p))}</td><td>${money(p.reduce((a,b)=>a+b,0)/p.length)}</td><td>${money(Math.max(...p))}</td></tr>`).join('')}
for(const id of ['search','cloud','stock'])$(id).addEventListener('input',render);$('model').addEventListener('change',draw);$('refresh').addEventListener('click',load);load();
